   228	        // store the credentials so the user doesn't need to login again after they finish their supportal
   229	        // action. This needs to computed before we call `redirectToSignIn`
   230	        if (!isSupportal && shouldStashSession) {
   231	            onyxSetParams = {
   232	                [ONYXKEYS.STASHED_CREDENTIALS]: credentials,
   233	                [ONYXKEYS.STASHED_SESSION]: session,
   234	            };
   235	        }
   236	        // If this is a supportal token, and we've received the parameters to stashSession as true, and
   237	        // we already have a stashedSession, that means we are supportaled, currently supportaling
   238	        // into another account and we want to keep the stashed data from the original account.
   239	        if (isSupportal && shouldStashSession && hasStashedSession()) {
   240	            onyxSetParams = {
   241	                [ONYXKEYS.STASHED_CREDENTIALS]: stashedCredentials,
   242	                [ONYXKEYS.STASHED_SESSION]: stashedSession,
